mapper.select:
SELECT id, store_id, zookie, operation, object_type, object_id, relation,
       subject_type, subject_id, subject_relation, operation_time
FROM fga_changelog
WHERE store_id = #{storeId}
  AND zookie > #{startZookie}

      AND zookie <= #{endZookie}

ORDER BY zookie ASC

    LIMIT #{limit}

SELECT id, store_id, zookie, operation, object_type, object_id, relation,
       subject_type, subject_id, subject_relation, operation_time
FROM fga_changelog
WHERE store_id = #{storeId}
  AND zookie > #{afterZookie}
ORDER BY zookie ASC

    LIMIT #{limit}

SELECT MAX(zookie)
FROM fga_changelog
WHERE store_id = #{storeId}

mapper.delete:
DELETE FROM fga_changelog
WHERE store_id = #{storeId}
  AND zookie < #{beforeZookie}
